// --- Brick bounce (issue #1): face, corner, push-out, seam, tunneling ------

// One live brick at 100,100. The ball overlaps it by 3 px on the target face.
const uneBrique = () => [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
const DT = 1 / 60;
const DT_MAX = 0.05;

function jouer(t, state, dt = DT) {
  const { vx, vy } = state.ball;
  const bouge = () => state.ball.vx !== vx || state.ball.vy !== vy;
  const contexte = new Proxy({}, { get: () => () => {}, set: () => true });
  frame(contexte, state);
  if (bouge()) return;
  step(state, dt);
  if (bouge()) {
    t.diagnostic('dévié par step() et non par frame()');
    return;
  }
  frame(contexte, state);
  if (bouge()) t.diagnostic('dévié par frame() après le déplacement de step()');
}

