// --- Physics (movement + wall/paddle/brick bounces) --------------------------

// Swept AABB contact between the ball and a brick over the movement from
// (prevX, prevY) to the ball's current position. The ball is a circle, so it
// is swept as a point against the brick expanded by its radius (Minkowski
// sum): exact for axis-aligned motion. This is what defeats tunneling: a step
// longer than the brick (ballSpeed(6) * 0.05 = 35.5 px > BRICK_H + 2*BALL_R =
// 34 px) still sees the crossing, where a discrete sample never does.
//
// Slab method: each axis gives the time interval (0..1 over the step) during
// which the point lies inside the expanded box; the overlap of the two
// intervals is the time the ball is inside. The axis whose entry time is the
// LATEST is the face that was hit first (side, top/bottom, or both on a
// corner). Returns { t, axis } or null when the trajectory misses the brick.
function sweptContact(ball, brick, prevX, prevY) {
  const left = brick.x - ball.r;
  const top = brick.y - ball.r;
  const right = brick.x + brick.w + ball.r;
  const bottom = brick.y + brick.h + ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let t1x, t2x;
  if (dx === 0) {
    if (prevX < left || prevX > right) return null;
    t1x = 0;
    t2x = Infinity;
  } else {
    t1x = (left - prevX) / dx;
    t2x = (right - prevX) / dx;
    if (t1x > t2x) [t1x, t2x] = [t2x, t1x];
  }
  let t1y, t2y;
  if (dy === 0) {
    if (prevY < top || prevY > bottom) return null;
    t1y = 0;
    t2y = Infinity;
  } else {
    t1y = (top - prevY) / dy;
    t2y = (bottom - prevY) / dy;
    if (t1y > t2y) [t1y, t2y] = [t2y, t1y];
  }

  const tEnter = Math.max(t1x, t1y);
  const tExit = Math.min(t2x, t2y);
  if (tEnter > tExit || tExit < 0) return null;

  if (tEnter <= 0) {
    // Overlapping at the start of the step: resolve statically, on the axis of
    // smallest penetration — both axes on a corner (equal penetration).
    const penX = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
    const penY = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
    const axis = penX < penY ? 'x' : penY < penX ? 'y' : 'both';
    return { t: 0, axis };
  }

  const axis = t1x > t1y ? 'x' : t1y > t1x ? 'y' : 'both';
  return { t: tEnter, axis };
}

// Breaks every live brick the ball touched during the step (score + combo),
// then applies ONE bounce — on the axis of the earliest contact — and pushes
// the ball back out of the brick. A single bounce per pass: the grid gap is
// BRICK_GAP (8 px) and the ball diameter 2*BALL_R (14 px), so a ball sitting
// on a seam overlaps two bricks and two flips would cancel — the ball would
// plow through (debt #1).
function resolveBricks(state, prevX, prevY) {
  const ball = state.ball;
  const contacts = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const hit = sweptContact(ball, brick, prevX, prevY);
    if (hit) contacts.push({ brick, ...hit });
  }
  if (contacts.length === 0) return;

  for (const { brick } of contacts) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // One bounce, from the earliest contact. The push-out is decided from the
  // CONTACT point, not the endpoint: a fast ball may have crossed the brick,
  // and the endpoint would put it on the wrong side of it.
  contacts.sort((a, b) => a.t - b.t);
  const { brick, axis, t } = contacts[0];
  const cx = prevX + (ball.x - prevX) * t;
  const cy = prevY + (ball.y - prevY) * t;

  if (axis === 'x' || axis === 'both') {
    ball.vx = -ball.vx;
    ball.x = cx < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  }
  if (axis === 'y' || axis === 'both') {
    ball.vy = -ball.vy;
    ball.y = cy < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
